pub mod ir;
pub mod rust;

use std::fmt;
use std::path::PathBuf;

use crate::backend::ir::Ir;
use crate::backend::rust::{Rust, RustDispatch};
use crate::config::Config;
use crate::ir::wire::Wire;
use crate::ir::{Role, Schema};

/// Every name [`protocol`] accepts, for listing in help and error messages.
pub const PROTOCOLS: &[&str] = &["ir", "rust"];
/// Every name [`dispatch`] accepts.
pub const DISPATCHERS: &[&str] = &["rust"];

/// What the first line of a generated file holds, where its format has
/// comments, so a stale one can be told apart from a hand-written one.
pub const MARKER: &str = "@generated by `ujuc";

/// Settings shared by every backend; each uses the ones that apply to it.
#[derive(Debug, Clone, Default)]
pub struct Options {
    /// Generate only this role, which encodes the messages it sends and
    /// decodes the ones it receives. `None` generates every role.
    pub role: Option<Role>,
    /// The options read from `ujuc.toml`. The `ir` backend ignores them:
    /// none is part of the protocol.
    pub config: Config,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GeneratedFile {
    pub path: PathBuf,
    pub contents: String,
}

impl GeneratedFile {
    pub fn new(path: impl Into<PathBuf>, contents: impl Into<String>) -> Self {
        GeneratedFile {
            path: path.into(),
            contents: contents.into(),
        }
    }
}

/// Emits source for one target language from a lowered [`Schema`].
pub trait Backend {
    fn generate(&self, schema: &Schema) -> Result<Vec<GeneratedFile>, Error>;
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error {
    pub message: String,
}

impl Error {
    pub fn new(message: impl Into<String>) -> Self {
        Error {
            message: message.into(),
        }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

impl std::error::Error for Error {}

/// Lays `schema` out for a backend. Lowering reports layout errors first, so
/// this fails only on a schema that was not lowered from source.
pub(crate) fn wire(schema: &Schema) -> Result<Wire, Error> {
    Wire::new(schema).map_err(|errors| {
        let messages: Vec<String> = errors
            .into_iter()
            .map(|error| format!("`{}`: {}", schema.qualified(error.def), error.message))
            .collect();
        Error::new(messages.join("\n"))
    })
}

/// Look up a protocol backend, emitting the types with their encoders and
/// decoders, by name; see [`PROTOCOLS`] for the accepted names.
pub fn protocol(name: &str, options: &Options) -> Option<Box<dyn Backend>> {
    match name {
        "ir" => Some(Box::new(Ir)),
        "rust" => Some(Box::new(Rust {
            role: options.role,
            map: options.config.rust.map.clone(),
        })),
        _ => None,
    }
}

/// Look up a dispatch backend, emitting handler branches for the messages
/// `role` receives, by name; see [`DISPATCHERS`] for the accepted names.
pub fn dispatch(name: &str, role: Role) -> Option<Box<dyn Backend>> {
    match name {
        "rust" => Some(Box::new(RustDispatch { role })),
        _ => None,
    }
}
